from lib import *
S = SS('t21')
steps = [
    step("一次全局事务的两个分支:账户扣 100、库存扣 3。AT 的分支在一个本地事务里完成“读前镜像、改、读后镜像、写 undo_log、申请全局锁”再本地提交。两个分支都已经本地提交、全局事务还没决定时:账户 RM 的 undo_log 里是 (xid-1, account, 1) 前镜像 balance=1000、后镜像 balance=900,库存 RM 的 undo_log 里是前镜像 qty=50、后镜像 qty=47,tc_db.global_lock 里有 acct.account:1 和 stock.stock:1 两行,别的会话此刻读到的账户是 900、库存是 47——新值已经对所有人可见。全局提交之后:undo_log 0 + 0 行、global_lock 0 行,账户 900、库存 47。全局提交只是清理。", t=tl(S(1)), mark=lidx(S(1), '账户 RM 的 undo_log', '别的会话此刻读到'), done=lidx(S(1), '全局提交之后'), b=bars([['全局提交前:undo_log 行数(两个 RM)', 2, '2'], ['全局提交前:global_lock 行数', 2, '2'], ['全局提交后:undo_log + global_lock 行数', 0, '0']], 2, mark=[0, 1], done=[2]), kv=KV([['分支提交', '本地事务立即提交,新值对所有人可见'], ['undo_log', '前镜像 + 后镜像'], ['全局提交', '只清理 undo_log 与全局锁']], ['分支提交'])),
    step("全局回滚:分支 1(账户扣 100)已本地提交,账户 900;分支 2(库存)失败,全局回滚。按 undo_log 的前镜像把账户恢复:回滚动作是 account#1 恢复成 balance=1000,之后账户 1000、库存 50,undo_log 行数 0、global_lock 行数 0。回滚不需要业务写任何补偿代码,靠的是框架保存的前镜像和后镜像。", t=tl(S(2)), mark=lidx(S(2), '分支 2(库存)失败'), done=lidx(S(2), '回滚动作'), b=bars([['分支 1 提交后账户', 900, '900'], ['全局回滚后账户', 1000, '1000'], ['回滚后 undo_log + global_lock 行数', 0, '0']], 1000, mark=[0], done=[1, 2]), kv=KV([['回滚依据', 'undo_log 里的前镜像'], ['回滚前校验', '当前值必须等于后镜像'], ['业务代码', '不用写补偿']], ['回滚依据'])),
    step("全局锁防止脏写。T1 改了账户 1 之后停 1 秒才决定;本地行锁在分支提交时就释放了,T2 想改同一行。有全局锁、T1 提交:T2 的分支在全局锁上等了 825 ms,T1 全局提交之后才拿到,最终账户 890(1000 - 100 - 10)。有全局锁、T2 只愿意等 0.3 s:T2 分支失败,acct.account:1 的全局锁被 T1 持有。没有全局锁、T1 决定回滚:T2 立刻成功(等 0 ms),T1 回滚失败——账户 1 当前值 890 不等于 T1 提交后的值 900,无法直接按前镜像恢复。本地锁在分支提交时放掉了,全局锁是接力保护这一行的东西。", t=tl(S(3)), mark=lidx(S(3), '没有全局锁、T1 决定回滚'), done=lidx(S(3), '有全局锁,T1 提交', '有全局锁、T2 只愿意等'), b=bars([['有全局锁:T2 等待 ms', 825, '825'], ['没有全局锁:T2 等待 ms', 0, '0'], ['没有全局锁:T1 回滚时账户当前值', 890, '890(≠ 900)']], 900, done=[0], mark=[1, 2]), kv=KV([['有全局锁', 'T2 等到 T1 全局提交'], ['没有全局锁', 'T2 立刻写,T1 回滚失败'], ['原因', '本地行锁分支提交后已释放']], ['原因'])),
    step("全局事务之外的写入也会造成脏写。没有全局事务、不知道全局锁的普通 UPDATE(加 5):T1 分支提交后,它立刻写入(等了 6 ms),T1 全局回滚失败(当前值 905 不等于后镜像 900),账户停在 905。让普通写入先检查全局锁(类似 Seata 的 @GlobalLock):它等了 542 ms,T1 回滚完成之后才写,T1 回滚成功,账户 1005(恢复成 1000 之后再加 5)。保护全局事务的数据,不只是全局事务之间互相检查,所有写入都要遵守。", t=tl(S(4)), mark=lidx(S(4), '普通写入不看全局锁'), done=lidx(S(4), '普通写入先看全局锁'), b=bars([['不看全局锁:T1 回滚时账户', 905, '905(回滚失败)'], ['先看全局锁:最终账户', 1005, '1005(回滚成功)'], ['先看全局锁:普通写入等待 ms', 542, '542']], 1010, mark=[0], done=[1], cur=[2]), kv=KV([['不看全局锁', '立刻写,T1 回滚失败(脏写)'], ['先看全局锁', '等 542 ms,T1 回滚成功'], ['结论', '所有写入都要遵守全局锁']], ['结论'])),
    step("读:分支已经本地提交、全局事务回滚之前,别人读到的就是“还没确定”的值(默认相当于全局读未提交)。100 个全局事务各“扣 100、停 20 ms、回滚”,另一个线程不停读余额:共读了 89438 次,余额值分布是 900(87586 次)和 1000(1852 次);读到 900——一个最终被回滚、从未真正生效的值——占 98%。需要读到“已经确定”的值时,读之前要先看全局锁,把读也串到全局事务后面。", t=tl(S(5)), mark=lidx(S(5), '读线程共读了'), done=lidx(S(5), '需要读到'), b=bars([['读到 900(被回滚的值)的次数', 87586, '87586'], ['读到 1000 的次数', 1852, '1852']], 89438, mark=[0], done=[1]), kv=KV([['默认读', '相当于全局读未提交'], ['读到的 900', '最终被回滚,从未真正生效'], ['要读确定值', '读之前先看全局锁']], ['默认读'])),
    step("代价:一次 AT 分支更新对比普通的本地更新(8 个线程各改自己的行,各 300 次,3 轮中位数)。普通本地更新:单次延迟中位数 357 µs、20739 次/秒。AT 分支(前镜像、改、后镜像、undo、全局锁、提交,加全局提交清理):1991 µs、3047 次/秒;再加上 TC 里记录全局事务的开始与状态:2365 µs、2282 次/秒。每次 AT 分支比普通更新多 4 条语句和一次全局提交时的清理;8 个线程互不冲突的行也遇到 3 次 InnoDB 死锁(1213),重试后成功。换来的是业务代码里只有普通的 SQL,不用写 Try / Confirm / Cancel。", t=tl(S(6)), mark=lidx(S(6), 'AT 分支'), done=lidx(S(6), '普通本地更新'), b=bars([['普通更新 µs', 357, '357'], ['AT 分支 µs', 1991, '1991'], ['AT + TC 记录 µs', 2365, '2365'], ['普通更新 次/秒', 20739, '20739'], ['AT 分支 次/秒', 3047, '3047']], 21000, cur=[0, 3], mark=[1, 2, 4]), kv=KV([['延迟', '357 µs → 1991 µs(AT 分支)'], ['吞吐', '20739 → 3047 次/秒'], ['换来', '业务代码只写普通 SQL']], ['换来'])),
]
